Convex 1.44.0. `files` has fields `storageId: v.id("_storage")`, `fileName: v.string()` and `size: v.number()`. Consider this attempted implementation:

```ts
import { mutation } from "./_generated/server";
import { v } from "convex/values";

export const uploadFile = mutation({
  args: { contents: v.string(), fileName: v.string() },
  handler: async (ctx, args) => {
    const blob = new Blob([args.contents]);
    const storageId = await ctx.storage.store(blob);
    const fileId = await ctx.db.insert("files", {
      storageId, fileName: args.fileName, size: blob.size,
    });
    const url = await ctx.storage.getUrl(storageId);
    return { fileId, storageId, url };
  },
});
```
